def search_matrix(matrix, target):
    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1                                                  # start at the top-right corner
    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1                                                       # too big: everything below in this column is even bigger, eliminate the column
        else:
            row += 1                                                       # too small: everything left in this row is even smaller, eliminate the row
    return False


if __name__ == "__main__":
    matrix = [[1, 4, 7, 11, 15], [2, 5, 8, 12, 19], [3, 6, 9, 16, 22], [10, 13, 14, 17, 24], [18, 21, 23, 26, 30]]
    print(search_matrix(matrix, 5))

