import java.util.*;

public class Main {
    boolean searchMatrix(int[][] matrix, int target) {
        int rows = matrix.length, cols = matrix[0].length;
        int row = 0, col = cols - 1;                                              // start at the top-right corner
        while (row < rows && col >= 0) {
            if (matrix[row][col] == target) {
                return true;
            } else if (matrix[row][col] > target) {
                col--;                                                             // too big: everything below in this column is even bigger, eliminate the column
            } else {
                row++;                                                             // too small: everything left in this row is even smaller, eliminate the row
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] matrix = {{1, 4, 7, 11, 15}, {2, 5, 8, 12, 19}, {3, 6, 9, 16, 22}, {10, 13, 14, 17, 24}, {18, 21, 23, 26, 30}};
        System.out.println(solution.searchMatrix(matrix, 5));
    }
}

